const cfg = $('Load config').first().json;
const input = $('When called').first().json;
const tz = cfg.timezone || 'America/New_York';
const now = DateTime.now().setZone(tz);
const [qsH, qsM] = String(cfg.quiet_start || '20:00').split(':').map(Number);
const [qeH, qeM] = String(cfg.quiet_end || '08:00').split(':').map(Number);
const mins = now.hour * 60 + now.minute;
const qs = qsH * 60 + qsM, qe = qeH * 60 + qeM;
let quiet;
if (qs > qe) quiet = (mins >= qs || mins < qe); else quiet = (mins >= qs && mins < qe);
const skip = String(input.skip_quiet_hours) === 'true';
const defer = quiet && !skip;
let resumeAt = null;
if (defer) {
  let r = now.set({ hour: qeH, minute: qeM, second: 0, millisecond: 0 });
  if (r <= now) r = r.plus({ days: 1 });
  resumeAt = r.toUTC().toISO();
}
return [{ json: { phone: input.phone, body: input.body, kind: input.kind, quiet, defer, resume_at: resumeAt, local_time: now.toFormat('HH:mm') } }];

const cfg = $('Load config').first().json;
const q = $('Quiet hours').first().json;
const prior = $('Prior outbound').all().filter(i => i.json && i.json.id);
let body = String(q.body || '');
const footer = String(cfg.stop_footer || '').trim();
// The registered A2P campaign promises the opt-out line on every message, so it goes on every customer text, not only the first.
if (footer && !body.toUpperCase().includes('STOP')) body = body + ' ' + footer;
return [{ json: { phone: q.phone, body, kind: q.kind, from: cfg.business_number, deferred: !!q.defer, first_message: prior.length === 0 } }];

const cfg = $('Load config').first().json;
const input = $('When called').first().json;
const ch = String(cfg.alert_channel || 'sms').toLowerCase();
const high = String(input.urgency || '').toLowerCase() === 'high';
const words = { new_lead: 'New lead', missed_call: 'Missed call', reply: 'Customer reply', cadence_done: 'Follow-up finished', error: 'Error', duplicate: 'Same lead again' };
return [{ json: {
  send_sms: ch === 'sms' || ch === 'both',
  send_email: ch === 'email' || ch === 'both',
  sms_text: (high ? 'NEW LEAD: ' : '') + String(input.text || ''),
  subject: (words[input.event] || input.event || 'Alert') + ' - ' + (cfg.business_name || ''),
  email_text: String(input.text || '') + (input.phone ? '\n\nContact: ' + input.phone : ''),
  from: cfg.business_number, owner_cell: cfg.owner_cell, owner_email: cfg.owner_email,
  event: input.event, phone: input.phone
} }];

const cfg = $('Load config').first().json;
const input = $('When called').first().json;
const contact = $('Find contact').first().json || {};
const tz = cfg.timezone || 'America/New_York';
const phone = String(input.phone || '');
const name = String(input.name || contact.name || '').trim();
const source = String(input.source || 'website_form');
const message = String(input.message || '').trim();
const sourceWords = { website_form: 'the website', missed_call: 'a missed call', google_lsa: 'Google', angi: 'Angi', facebook: 'Facebook', manual: 'manual entry' };
const fill = s => String(s || '')
  .replace(/\{business_name\}/g, cfg.business_name || '')
  .replace(/\{name\}/g, name || 'no name given')
  .replace(/\{source\}/g, sourceWords[source] || source);
const d = phone.replace(/\D/g, '');
const pretty = d.length === 11 ? '(' + d.slice(1, 4) + ') ' + d.slice(4, 7) + '-' + d.slice(7) : phone;
const esc = s => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
const base = 'https://__N8N_HOST__/webhook/bridge-connect';
const action = base + '?to=' + encodeURIComponent(phone) + '&from=' + encodeURIComponent(cfg.business_number || '');
const whisper = fill(cfg.bridge_whisper || 'New lead from {source}, {name}. Press 1 to connect.');
const twiml = '<Response><Gather numDigits="1" timeout="8" action="' + esc(action) + '" method="POST"><Say>' + esc(whisper) + '</Say><Say>' + esc(whisper) + '</Say></Gather><Say>No answer received. Goodbye.</Say></Response>';
let n3 = DateTime.now().setZone(tz).plus({ hours: 1 }).plus({ days: 1 }).set({ hour: 9, minute: 0, second: 0, millisecond: 0 });
while (n3.weekday > 5) n3 = n3.plus({ days: 1 });
return [{ json: {
  phone, name, source, message, pretty,
  consent: contact.consent || 'opted_in',
  known: !!contact.id,
  instant_text: fill(cfg.lead_instant_text),
  nudge_1: fill(cfg.lead_nudge_1_text),
  nudge_2: fill(cfg.lead_nudge_2_text),
  nudge_3: fill(cfg.lead_nudge_3_text),
  owner_text: 'New lead from ' + (sourceWords[source] || source) + ': ' + (name || 'no name') + ' ' + pretty + (message ? '. "' + message + '"' : '') + '. Texted them already.',
  bridge: source !== 'missed_call' && !!cfg.owner_cell,
  bridge_twiml: twiml,
  from: cfg.business_number, owner_cell: cfg.owner_cell,
  nudge_3_at: n3.toUTC().toISO()
} }];

const cfg = $('Load config (help)').first().json;
const n = String(cfg.business_number || '').replace(/\D/g, '');
const pretty = n.length === 11 ? '(' + n.slice(1, 4) + ') ' + n.slice(4, 7) + '-' + n.slice(7) : cfg.business_number;
const text = String(cfg.help_text || '{business_name}. Reply STOP to opt out.')
  .replace(/\{business_name\}/g, cfg.business_name || '')
  .replace(/\{business_number_pretty\}/g, pretty || '');
return [{ json: { phone: $('Normalize').first().json.phone, body: text } }];

const b = $json.body || {};
const raw = String(b.phone || b.Phone || b.mobile || '');
const d = raw.replace(/\D/g, '');
let phone = '';
if (d.length === 10) phone = '+1' + d;
else if (d.length === 11 && d.startsWith('1')) phone = '+' + d;
else if (d.length > 11) phone = '+' + d;
if (!phone) throw new Error('Lead has no usable phone number: ' + JSON.stringify(b));
return [{ json: {
  phone,
  name: String(b.name || b.Name || ((b.first_name || '') + ' ' + (b.last_name || '')).trim() || ''),
  source: String(b.source || 'website_form'),
  message: String(b.message || b.Message || b.notes || '') + (b.address ? ' Address: ' + b.address : '')
} }];

const cfg = $('Load config').first().json || {};
const b = $('Quote sent').first().json.body || {};
const digits = String(b.phone || '').replace(/[^0-9]/g, '');
let phone = '';
if (digits.length === 10) phone = '+1' + digits;
else if (digits.length === 11 && digits.startsWith('1')) phone = '+' + digits;
else if (digits.length > 11) phone = '+' + digits;
const pretty = phone ? phone.replace(/^\+1(\d{3})(\d{3})(\d{4})$/, '($1) $2-$3') : '';
const name = String(b.name || '').trim();
const who = name || pretty || 'there';
const amount = String(b.amount || '').trim();
const job = String(b.job || 'the work').trim();
const url = String(b.quote_url || '').trim();
const biz = cfg.business_name || 'us';
const owner = cfg.owner_name || 'the owner';
const money = amount ? (amount.startsWith('$') ? amount : '$' + amount) : '';

// Waits are config driven so an owner can retune the chase without touching nodes.
// Read numbers explicitly. A plain `cfg.x || default` would throw away a configured 0,
// which is exactly the value you want while testing.
const num = (v, dflt) => {
  if (v === null || v === undefined || String(v).trim() === '') return dflt;
  const n = Number(v);
  return Number.isFinite(n) && n >= 0 ? n : dflt;
};
const d1 = num(cfg.quote_wait_1_days, 2);
const d2 = num(cfg.quote_wait_2_days, 3);
const d3 = num(cfg.quote_wait_3_days, 4);
const tz = cfg.timezone || 'America/New_York';
const now = DateTime.now().setZone(tz);
// A wait of a day or more lands at 10am local rather than whatever time the quote went out.
// A shorter wait fires as soon as it is due, so setting the waits to 0 for a test does not
// park the run until tomorrow morning.
const at = (days) => days >= 1
  ? now.plus({ days }).set({ hour: 10, minute: 0, second: 0, millisecond: 0 }).toUTC().toISO()
  : now.plus({ days }).toUTC().toISO();

const fill = (t, dflt) => String(t || dflt)
  .replace(/\{name\}/g, who).replace(/\{business\}/g, biz).replace(/\{owner\}/g, owner)
  .replace(/\{amount\}/g, money).replace(/\{job\}/g, job).replace(/\{link\}/g, url).trim();

return [{ json: {
  ok: !!phone,
  phone, pretty, name, amount: money, job, url,
  source: 'quote',
  nudge_1: fill(cfg.quote_nudge_1_text, 'Hi {name}, just checking you got the quote from {business} for {job}. Any questions at all, reply here.'),
  nudge_2: fill(cfg.quote_nudge_2_text, 'Hi {name}, following up on the {job} quote. Happy to walk through it or adjust the scope if the number is off. Just reply.'),
  nudge_3: fill(cfg.quote_nudge_3_text, 'Last one from me {name}. If the timing is not right no problem, and if you want to go ahead just reply and {owner} will get you booked in.'),
  nudge_1_at: at(d1), nudge_2_at: at(d1 + d2), nudge_3_at: at(d1 + d2 + d3),
  owner_text: 'Quote chase started for ' + who + ' ' + pretty + (money ? ' at ' + money : '') + ' for ' + job + '.'
} }];

const cfg = $('Load config').first().json || {};
const b = $('Invoice sent').first().json.body || {};

const digits = String(b.phone || '').replace(/[^0-9]/g, '');
let phone = '';
if (digits.length === 10) phone = '+1' + digits;
else if (digits.length === 11 && digits.startsWith('1')) phone = '+' + digits;
else if (digits.length > 11) phone = '+' + digits;
const pretty = phone ? phone.replace(/^\+1(\d{3})(\d{3})(\d{4})$/, '($1) $2-$3') : '';

const name = String(b.name || '').trim();
const who = name || pretty || 'there';
const amountRaw = String(b.amount || '').trim();
const money = amountRaw ? (amountRaw.startsWith('$') ? amountRaw : '$' + amountRaw) : '';
const invoiceId = String(b.invoice_id || '').trim();
const url = String(b.invoice_url || '').trim();
const biz = cfg.business_name || 'us';
const owner = cfg.owner_name || 'the owner';

// Read numbers explicitly so a configured 0 is honoured instead of falling back.
const num = (v, dflt) => {
  if (v === null || v === undefined || String(v).trim() === '') return dflt;
  const n = Number(v);
  return Number.isFinite(n) && n >= 0 ? n : dflt;
};

const tz = cfg.timezone || 'America/New_York';
const now = DateTime.now().setZone(tz);

// The due date drives everything. If the caller gives one we use it. If not we fall back to
// the configured terms. A due date already in the past means the first reminder is due now.
let due = null;
if (b.due_date) {
  const parsed = DateTime.fromISO(String(b.due_date), { zone: tz });
  if (parsed.isValid) due = parsed;
}
if (!due) due = now.plus({ days: num(cfg.invoice_due_days, 7) });

const gap2 = num(cfg.invoice_wait_2_days, 3);
const gap3 = num(cfg.invoice_wait_3_days, 4);

// Reminders land at 10am local. One already past its moment fires as soon as the run reaches it,
// which is what you want for a test and for an invoice that was already overdue when it arrived.
const at = (dt) => {
  const target = dt.set({ hour: 10, minute: 0, second: 0, millisecond: 0 });
  return (target < now ? now : target).toUTC().toISO();
};
const dueLabel = due.toFormat('cccc LLL d');

const fill = (t, dflt) => String(t || dflt)
  .replace(/\{name\}/g, who)
  .replace(/\{business\}/g, biz)
  .replace(/\{owner\}/g, owner)
  .replace(/\{amount\}/g, money || 'the invoice')
  .replace(/\{link\}/g, url)
  .replace(/\{due\}/g, dueLabel)
  .replace(/\{invoice\}/g, invoiceId)
  .replace(/\s+/g, ' ')
  .trim();

return [{ json: {
  ok: !!phone,
  phone, pretty, name, amount: money, invoice_id: invoiceId, url,
  due_label: dueLabel,
  nudge_1: fill(cfg.invoice_nudge_1_text, 'Hi {name}, friendly reminder from {business}: the invoice for {amount} is due {due}. {link} Any questions just reply to this text.'),
  nudge_2: fill(cfg.invoice_nudge_2_text, 'Hi {name}, the {amount} invoice from {business} is past due now. If something is wrong with it just reply and {owner} will sort it out. {link}'),
  nudge_3: fill(cfg.invoice_nudge_3_text, 'Last reminder from me {name}, on the {amount} invoice from {business}. If you need more time or a payment plan, reply and we will work it out. {link}'),
  nudge_1_at: at(due),
  nudge_2_at: at(due.plus({ days: gap2 })),
  nudge_3_at: at(due.plus({ days: gap2 + gap3 })),
  owner_text: 'Invoice reminders started for ' + who + ' ' + pretty + (money ? ' at ' + money : '') + (invoiceId ? ' (' + invoiceId + ')' : '') + ', due ' + dueLabel + '.'
} }];

const cfg = $('Load config (paid)').first().json || {};
const b = $('Invoice paid').first().json.body || {};

const digits = String(b.phone || '').replace(/[^0-9]/g, '');
let phone = '';
if (digits.length === 10) phone = '+1' + digits;
else if (digits.length === 11 && digits.startsWith('1')) phone = '+' + digits;
else if (digits.length > 11) phone = '+' + digits;
const pretty = phone ? phone.replace(/^\+1(\d{3})(\d{3})(\d{4})$/, '($1) $2-$3') : '';

const name = String(b.name || '').trim();
const who = name || pretty || 'there';
const amountRaw = String(b.amount || '').trim();
const money = amountRaw ? (amountRaw.startsWith('$') ? amountRaw : '$' + amountRaw) : '';
const biz = cfg.business_name || 'us';

// Sending a receipt text is opt out, not opt in. An owner who does not want it sets
// invoice_receipt_text to the word off rather than hunting for a node to delete.
const raw = cfg.invoice_receipt_text;
const off = String(raw || '').trim().toLowerCase() === 'off';

const body = String(raw && !off ? raw : 'Thanks {name}, we have your payment{amount} at {business}. Appreciate the business.')
  .replace(/\{name\}/g, who)
  .replace(/\{business\}/g, biz)
  .replace(/\{amount\}/g, money ? ' of ' + money : '')
  .replace(/\s+/g, ' ')
  .trim();

return [{ json: {
  ok: !!phone,
  send_receipt: !!phone && !off,
  phone, pretty, name, amount: money, body,
  owner_text: 'Payment received from ' + who + ' ' + pretty + (money ? ' for ' + money : '') + '. Reminders stopped.'
} }];

const cfg = $('Load config').first().json || {};
const tz = cfg.timezone || 'America/New_York';
const now = DateTime.now().setZone(tz);

const num = (v, dflt) => {
  if (v === null || v === undefined || String(v).trim() === '') return dflt;
  const n = Number(v);
  return Number.isFinite(n) && n >= 0 ? n : dflt;
};

// How far back the brief looks. 24 hours by default, so a 7am run covers 7am yesterday on.
const hours = num(cfg.brief_lookback_hours, 24);
const since = now.minus({ hours });

// Every data table row carries createdAt, which is what the windows below are built on.
// Nothing here depends on a column an owner has to remember to fill in.
const rows = (name) => {
  try { return $(name).all().map(i => i.json).filter(r => r && r.id !== undefined); }
  catch (e) { return []; }
};
const inWindow = (r, field) => {
  const v = r && r[field];
  if (!v) return false;
  const d = DateTime.fromISO(String(v));
  return d.isValid && d >= since;
};

const contacts = rows('Contacts');
const cadences = rows('Cadences');
const messages = rows('Messages');
const reviews  = rows('Reviews');

const newContacts = contacts.filter(r => inWindow(r, 'createdAt'));

const recentMsgs = messages.filter(r => inWindow(r, 'createdAt'));
const inbound = recentMsgs.filter(r => r.direction === 'in');
const outbound = recentMsgs.filter(r => r.direction === 'out');
const inboundNumbers = [...new Set(inbound.map(r => r.phone).filter(Boolean))];

// Waiting on you: the newest message on that number came in, not out. This is the number
// that actually costs money, so it goes near the top and names the numbers.
const newest = {};
for (const m of messages) {
  const t = DateTime.fromISO(String(m.createdAt || ''));
  if (!t.isValid || !m.phone) continue;
  if (!newest[m.phone] || t > newest[m.phone].t) newest[m.phone] = { t, direction: m.direction };
}
const waiting = Object.keys(newest).filter(p => newest[p].direction === 'in');

const activeNow = cadences.filter(r => r.status === 'active');
const startedToday = cadences.filter(r => inWindow(r, 'createdAt'));
const stoppedToday = cadences.filter(r => r.stopped_at && inWindow(r, 'stopped_at'));
const stoppedBy = {};
for (const r of stoppedToday) stoppedBy[r.status] = (stoppedBy[r.status] || 0) + 1;

const asked = reviews.filter(r => inWindow(r, 'createdAt'));
const scored = reviews.filter(r => r.replied_at && inWindow(r, 'replied_at') && r.score !== null && r.score !== undefined);
const lowMark = num(cfg.review_low_score, 4);
const lows = scored.filter(r => Number(r.score) < lowMark);

const pretty = (p) => String(p || '').replace(/^\+1(\d{3})(\d{3})(\d{4})$/, '($1) $2-$3');
const plural = (n, one, many) => n + ' ' + (n === 1 ? one : many);

const owner = cfg.owner_name || 'there';
const lines = [];

if (waiting.length) {
  lines.push(plural(waiting.length, 'conversation is', 'conversations are') + ' waiting on you: ' +
             waiting.slice(0, 3).map(pretty).join(', ') + (waiting.length > 3 ? ' and more' : ''));
}
if (newContacts.length) lines.push(plural(newContacts.length, 'new contact', 'new contacts'));
if (inbound.length) lines.push(plural(inbound.length, 'text in', 'texts in') + ' from ' + plural(inboundNumbers.length, 'number', 'numbers'));
if (outbound.length) lines.push(plural(outbound.length, 'text', 'texts') + ' sent');
if (startedToday.length) lines.push(plural(startedToday.length, 'follow up started', 'follow ups started'));
if (Object.keys(stoppedBy).length) {
  lines.push('closed: ' + Object.keys(stoppedBy).map(k => stoppedBy[k] + ' ' + k.replace(/_/g, ' ')).join(', '));
}
if (activeNow.length) lines.push(plural(activeNow.length, 'follow up', 'follow ups') + ' still running');
if (asked.length) lines.push(plural(asked.length, 'review ask', 'review asks') + ' went out');
if (scored.length) {
  const avg = (scored.reduce((s, r) => s + Number(r.score), 0) / scored.length);
  lines.push(plural(scored.length, 'review score', 'review scores') + ' back, average ' + (Math.round(avg * 10) / 10));
}
if (lows.length) lines.push(plural(lows.length, 'low score', 'low scores') + ' to look at: ' + lows.slice(0, 3).map(r => pretty(r.phone)).join(', '));

// Whether the day was quiet is decided on activity INSIDE the window only.
// 'waiting on you' and 'follow ups still running' are standing backlog, not activity:
// they can be non-empty for weeks, and counting them meant the brief was never quiet
// and brief_skip_if_empty could never fire. Found by testing on 2026-09-20.
const windowed = newContacts.length + recentMsgs.length + startedToday.length
  + stoppedToday.length + asked.length + scored.length;
const quiet = windowed === 0;
const header = 'Morning ' + owner + '. Last ' + hours + ' hours:';
const quietBody = waiting.length
  ? 'Morning ' + owner + '. Quiet ' + hours + ' hours, nothing new came in. '
    + plural(waiting.length, 'conversation is', 'conversations are') + ' still waiting on you: '
    + waiting.slice(0, 3).map(pretty).join(', ') + (waiting.length > 3 ? ' and more' : '') + '.'
  : 'Morning ' + owner + '. Quiet ' + hours + ' hours, nothing came in and nothing is waiting on you.';
const body = quiet ? quietBody : header + ' ' + lines.join('. ') + '.';

// An owner who only wants a text when something happened sets brief_skip_if_empty to yes.
const skipEmpty = ['yes', 'true', '1', 'on'].includes(String(cfg.brief_skip_if_empty || '').trim().toLowerCase());

return [{ json: {
  send: !(quiet && skipEmpty),
  quiet,
  body,
  counts: {
    waiting: waiting.length, new_contacts: newContacts.length,
    inbound: inbound.length, outbound: outbound.length,
    cadences_started: startedToday.length, cadences_active: activeNow.length,
    review_asks: asked.length, review_scores: scored.length, low_scores: lows.length
  }
} }];
